fn hrtimer_get_expires(timer: *const hrtimer) -> i64 {
unsafe { (*timer).node.expires }
}

fn hrtimer_get_softexpires(timer: *const hrtimer) -> i64 {
unsafe { (*timer)._softexpires }
}

fn hrtimer_highres_enabled() -> bool {
static_branch_likely__2!(unsafe { core::ptr::addr_of_mut!(hrtimer_highres_enabled_key) }) != 0
}

fn hrtimer_start(timer: *mut hrtimer, tim: i64, mode: u32) {
unsafe { hrtimer_start_range_ns(timer, tim, 0u64, mode) };
}

