fn tick_broadcast_enter() -> i32 {
unsafe { tick_broadcast_oneshot_control(1u32) }
}

fn tick_broadcast_exit() {
unsafe { tick_broadcast_oneshot_control(0u32) };
}

fn rt_prio(prio: i32) -> bool {
unlikely__2!(prio < 100 && prio >= 0) != 0
}

fn rt_or_dl_prio(prio: i32) -> bool {
unlikely__2!(prio < 100) != 0
}

fn rt_task(p: *mut task_struct) -> bool {
rt_prio(unsafe { (*p).prio })
}

fn rt_or_dl_task_policy(tsk: *mut task_struct) -> bool {
let policy: i32 = (unsafe { (*tsk).policy }) as i32;
if policy == 1 || policy == 2 {
return true;
}
if policy == 6 {
return true;
}
false
}

fn rt_mutex_get_top_task(p: *mut task_struct) -> *mut task_struct {
unsafe { (*p).pi_top_task }
}

// default timeslice is 100 msecs (used only for SCHED_RR tasks).
// Timeslices get refilled after they expire.
fn vtime_generic_enabled_cpu(cpu: i32) -> bool {
context_tracking_enabled_cpu(cpu)
}

fn vtime_generic_enabled_this_cpu() -> bool {
context_tracking_enabled_this_cpu()
}

